def solve(grid, start, goal):

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and (grid[r][c] == '.')

    def fn_1(frontier, visited, other_visited, get_neighbors):
        if not frontier:
            return None
        for _ in range(len(frontier)):
            r, c = frontier.popleft()
            if (r, c) in other_visited:
                return (r, c)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = (r + dr, c + dc)
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    frontier.append((nr, nc))
        return None
    if start == goal:
        return [start] if is_valid(*start) else []
    if not (is_valid(*start) and is_valid(*goal)):
        return []
    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_visited = {start}
    backward_visited = {goal}
    intersect_node = None
    while forward_queue and backward_queue:
        intersect = fn_1(forward_queue, forward_visited, backward_visited, lambda r, c: [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if is_valid(r + dr, c + dc)])
        if intersect:
            intersect_node = intersect
            break
        intersect = fn_1(backward_queue, backward_visited, forward_visited, lambda r, c: [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if is_valid(r + dr, c + dc)])
        if intersect:
            intersect_node = intersect
            break
    if not intersect_node:
        return []

    def build_path(start, end):
        path = []
        q = deque()
        q.append((start, [start]))
        visited = set([start])
        while q:
            curr, p = q.popleft()
            if curr == end:
                return p
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = (curr[0] + dr, curr[1] + dc)
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append(((nr, nc), p + [(nr, nc)]))
        return []
    first_path = build_path(start, intersect_node)
    second_path = build_path(goal, intersect_node)
    return first_path + second_path[::-1][1:] if first_path and second_path else []

