import heapq

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:

    def is_valid(pos: Tuple[int, int]) -> bool:
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and (grid[r][c] == '.')

    def manhattan(a: Tuple[int, int], b: Tuple[int, int]) -> int:
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(limit: int, pos: Tuple[int, int], came_from: Dict[Tuple[int, int], Tuple[int, int]]) -> Optional[int]:
        g = len(came_from)
        h = manhattan(pos, goal)
        f = g + h
        if f > limit:
            return f
        if pos == goal:
            return True
        best = float('inf')
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_pos = (pos[0] + dr, pos[1] + dc)
            if is_valid(next_pos) and next_pos not in came_from:
                came_from[next_pos] = pos
                res = search(limit, next_pos, came_from)
                if res is True:
                    return True
                if res < best:
                    best = res
                came_from.pop(next_pos)
        return best
    if not is_valid(start) or not is_valid(goal):
        return []
    if start == goal:
        return [start]

    def fn_1() -> List[Tuple[int, int]]:
        limit = manhattan(start, goal)
        came_from = {start: None}
        while True:
            t = search(limit, start, came_from)
            if t is True:
                break
            if t is None:
                return []
            if t == float('inf'):
                return []
            limit = t
            came_from = {start: None}
        path = []
        curr = goal
        while curr is not None:
            path.append(curr)
            curr = came_from[curr]
        path.reverse()
        return path
    result = fn_1()
    return result if result[0] == start else []

