        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r: int, c: int) -> bool:
        return not in_bounds(r, c) or grid[r][c] == '#'

    def heuristic(pos: Tuple[int, int]) -> int:
        r, c = pos
        gr, gc = goal
        return abs(r - gr) + abs(c - gc)

    def search(limit: int, pos: Tuple[int, int], visited: Set[Tuple[int, int]]) -> Optional[List[Tuple[int, int]]]:
        if pos == goal:
            return [pos]
