from typing import List, Tuple, Set, Optional

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:

    def heuristic(pos: Tuple[int, int]) -> int:
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def is_valid(pos: Tuple[int, int]) -> bool:
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and (grid[r][c] == '.')

    def search(limit: int, pos: Tuple[int, int], path: List[Tuple[int, int]], visited: Set[Tuple[int, int]]) -> Optional[List[Tuple[int, int]]]:
        f = len(path) - 1 + heuristic(pos)
        if f > limit:
            return None
        if pos == goal:
            return path
        min_cost = None
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            next_pos = (pos[0] + dr, pos[1] + dc)
            if not is_valid(next_pos) or next_pos in visited:
                continue
            visited.add(next_pos)
            result = search(limit, next_pos, path + [next_pos], visited)
            if result:
                return result
            visited.remove(next_pos)
        return min_cost
    if not (is_valid(start) and is_valid(goal)):
        return []
    if start == goal:
        return [start]
    limit = heuristic(start)
    while True:
        visited = set([start])
        result = search(limit, start, [start], visited)
        if result:
            return result
        elif result is None and limit >= 10 ** 6:
            return []
        limit += 1

