        curr = meeting_point
        while curr in came_from_forward:
            curr = came_from_forward[curr]
            path.insert(0, curr)
        curr = meeting_point
        while curr in came_from_backward:
            curr = came_from_backward[curr]
            path.append(curr)
        return path
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    if start == goal:
        if is_valid(*start):
            return [start]
        else:
            return []
    if not (is_valid(*start) and is_valid(*goal)):
        return []
    open_forward = [(0, start)]
    open_backward = [(0, goal)]
    came_from_forward = {}
    came_from_backward = {}
